    load(paste0("../bacon/Cores/",core.data[[station_id]]$entity,"/rho_depth_given_age.rdata"))
#     if( max(output$age[[1]]) >= 20000 ) age.reso <- 3
    rho_depth_given_age <- output$rho_depth_given_age[[age.reso]]
    depth <- output$depth
    site.age <- age <- output$age[[age.reso]]

    if( length(rho_depth_given_age) == 0 ){
