which_depths <- core.data[[station_id]]$depth %in% depth
if( any(which_depths == FALSE) ){
    depth <- output$depth
    if( length(depth) != nrow(all.avail) ) all.avail <- all.avail[which_depths,]
}

if( !all(sort(depth) == depth) ) depth <- sort(depth)

if( any(duplicated(depth)) ){
    dupl.id <- which(duplicated(depth))
#     depth[dupl.id] <- [dupl.id-1]*1.001
    depth <- depth[-dupl.id]
    all.avail <- all.avail[-dupl.id,]
}

source("src/check_ages.R")



#------------------------------------------------------------------------------
# choose those values from the bacon model which are used actually
#------------------------------------------------------------------------------

rho.d.g.a <- array(NA, dim = c(length(age), length(depth)))
for(i in 1:length(age)){
    for(j in 1:length(depth)){
        rho.d.g.a[i,j] <- rho_depth_given_age[i,(depth[j]-min(depth, na.rm = T))+1] 
    }
    rho.d.g.a[i,] <- rho.d.g.a[i,] / sum(rho.d.g.a[i,])
}

# to include every depth slice. zeros would remove some slices 
rho.d.g.a[which(rho.d.g.a == 0, arr.ind = T)] <- 10e-10 


# smooth some smoothing kernels of the age-depth relation. Due to low sedimentation rate 
if(sitename == "Birkat Ram"){
    which_depth_ids <- c(144:146)
    for(i in 1:3){
        df_temp <- data.frame(y=rho.d.g.a[,which_depth_ids[i]],x=c(1:length(age)))
        loess_fit <- loess(df_temp$y ~ df_temp$x, data=df_temp,span=0.05)
        smoothed_values <- predict(loess_fit)
        rho.d.g.a[,which_depth_ids[i]] <- smoothed_values
    }
    for(i in 1:length(age)) rho.d.g.a[i,] <- rho.d.g.a[i,] / sum(rho.d.g.a[i,])
    rho.d.g.a[which(rho.d.g.a <= 0, arr.ind = T)] <- 10e-10 
}

if(null.ratio.check ){
    null.ratio <- c()
    for(i in 1:ncol(all.avail)){
        null.ratio[i] <- length(which(all.avail[,i] == 0)) /  nrow(all.avail) 
    }
    # keep all available relict taxa 
    if(sitename == "Lake Ohrid"){
        relict.id <- c(3,8,23,24,25)
        null.ratio[relict.id] <- 0
        # remove pinus sylvestris
        null.ratio[1] <- 1
    }

    # remove the rarest taxa and limit the core to 15 taxa 
    rm.id1 <- which(null.ratio >= 0.95)
    if(ncol(all.avail) - length(rm.id1) > 15) metro_hastings <- TRUE
    if(!metro_hastings){
        rm.id <- which(null.ratio %in% sort(null.ratio)[16:ncol(all.avail)])
        if( length(rm.id) == ncol(all.avail) ) next()
        if( length(rm.id) >= 1 ) all.avail <- all.avail[,-rm.id]
        sorting.available.spectrum <-  colMeans(all.avail, na.rm = T)
    }else{
        # remove the rarest taxa
        rm.id <- which(null.ratio >= 0.95)
        if( length(rm.id) == ncol(all.avail) ) next()
        if( length(rm.id) >= 1 ) all.avail <- all.avail[,-rm.id]
        sorting.available.spectrum <-  colMeans(all.avail, na.rm = T)
    }

}


all.avail[all.avail == 0] <- 1e-6



#-------------------------------------------------------------------------------------------------------------------------
# age-depth trafo
#-------------------------------------------------------------------------------------------------------------------------

all.avail.age <- array(NA, dim = c(length(age),ncol(all.avail)))
for(i in 1:ncol(all.avail)){
    all.avail.age[,i] <-   rho.d.g.a %*% as.matrix(all.avail[,i])
}

if(anyNA(all.avail.age)){
    which_na <- which(is.na(rowMeans(all.avail.age)))
    for(i in 1:ncol(all.avail.age)){
        all.avail.age[which_na,i] <- all.avail.age[which_na[1]-1,i]
    }
}

load("data/in/core/core_data.rdata")
ages <- c()
for(i in 1:length(core_data$depths)) ages[i] <- round(mean(Bacon.Age.d(core_data$depths[i])))


#-------------------------------------------------------------------------------------------------------------
# Bacon.d.Age function
#-------------------------------------------------------------------------------------------------------------


Bacon.d.Age <- function( a, set = get("info")){
    ages <- cbind(set$output[, 1])
    for (i in 1:set$K) ages <- cbind(ages, ages[, i] + (set$thick * (set$output[, i + 1])))
    accs <- c()
    depth.g.age <- vector("list", length = (ncol(ages)-1))
    for (i in 2:ncol(ages)) {
        these <- (ages[, i - 1] < a) * (ages[, i] > a)
        if (sum(these) > 0){ 
            accs <- set$output[which(these > 0), i]
            depth.g.age[[i-1]] <- set$elbows[i-1] +  (1/accs) * ( a - ages[which(these > 0), i - 1]) 
        }
    }    
    return(unlist(depth.g.age))
}

#-------------------------------------------------------------------------------------------------------------

rho_depth_given_age <- array(NA, dim = c(length(core_data$depths), max(core_data$depths)))
for(i in 1:length(ages)){
    rho_depth_given_age_temp <- density(Bacon.d.Age(ages[i]), from = min(core_data$depths), to = max(core_data$depths), n = max(core_data$depths), na.rm = T)
    rho_depth_given_age_temp$y <- rho_depth_given_age_temp$y/sum(rho_depth_given_age_temp$y)
    rho_depth_given_age[i,] <- rho_depth_given_age_temp$y
}

#-------------------------------------------------------------------------------------------------------------

output <- list()
output$rho_depth_given_age  <- rho_depth_given_age
output$age  <- ages
output$depth  <- core_data$depths

save(output, file = "data/out/age_depth/rho_depth_given_age.rdata")
